@font-face {
  font-family: 'Bebas Neue';
  src: url('./fonts/BebasNeue.ttf') format('truetype');
  font-weight: 400;
  font-display: swap;
}
@font-face {
  font-family: 'Barlow Condensed';
  src: url('./fonts/BarlowCondensed-500.ttf') format('truetype');
  font-weight: 500;
  font-display: swap;
}
@font-face {
  font-family: 'Barlow Condensed';
  src: url('./fonts/BarlowCondensed-700.ttf') format('truetype');
  font-weight: 700;
  font-display: swap;
}
@font-face {
  font-family: 'Bangers';
  src: url('./fonts/Bangers.ttf') format('truetype');
  font-weight: 400;
  font-display: swap;
}

:root {
  --ink: #05080d;
  --ink-2: #0a1019;
  --panel: rgba(7, 13, 21, 0.72);
  --panel-solid: #09111b;
  --steel: #9db3c6;
  --ice: #bdefff;
  --cyan: #66e5ff;
  --cyan-deep: #1b9fc4;
  --gold: #ffd36a;
  --gold-deep: #b98219;
  --red: #ff3d4f;
  --red-deep: #8e101d;
  --white: #f4fbff;
  --font-display: 'Bebas Neue', 'Arial Narrow', Impact, sans-serif;
  --font-ui: 'Barlow Condensed', 'Arial Narrow', sans-serif;
  --font-impact: 'Bangers', 'Bebas Neue', cursive;
  --safe-t: env(safe-area-inset-top, 0px);
  --safe-r: env(safe-area-inset-right, 0px);
  --safe-b: env(safe-area-inset-bottom, 0px);
  --safe-l: env(safe-area-inset-left, 0px);
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  background: var(--ink);
  color: var(--white);
  overflow: hidden;
  overscroll-behavior: none;
  -webkit-user-select: none;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
  font-family: var(--font-ui);
}

body { position: fixed; inset: 0; }

#app {
  position: absolute;
  inset: 0;
  overflow: hidden;
  background: #05080d;
}

#game-canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  cursor: grab;
}
#game-canvas:active { cursor: grabbing; }

.hidden { display: none !important; }

/* ---------------- global effects ---------------- */

.vignette {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(ellipse at 50% 44%, transparent 38%, rgba(0, 0, 0, 0.42) 78%, rgba(0, 0, 0, 0.82) 100%),
    linear-gradient(180deg, rgba(0, 0, 0, 0.42) 0%, transparent 17%, transparent 76%, rgba(0, 0, 0, 0.45) 100%);
  z-index: 4;
}

#damage-vignette {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0;
  z-index: 7;
  background: radial-gradient(ellipse at center, transparent 34%, rgba(255, 22, 44, 0.35) 75%, rgba(150, 0, 12, 0.78) 100%);
  transition: opacity 0.35s ease;
}
#damage-vignette.hit {
  opacity: 1;
  transition: opacity 0.05s ease;
}
#damage-vignette.critical { animation: criticalPulse 1.4s ease-in-out infinite; }
@keyframes criticalPulse { 0%, 100% { opacity: 0.2; } 50% { opacity: 0.62; } }

#flash {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0;
  z-index: 8;
  background: #eafcff;
  mix-blend-mode: screen;
}
#flash.fire { animation: flashFire 0.34s ease-out; }
#flash.fire-red { animation: flashFireRed 0.4s ease-out; }
@keyframes flashFire {
  0% { opacity: 0.85; } 100% { opacity: 0; }
}
@keyframes flashFireRed {
  0% { opacity: 0.55; background: #ff2338; } 100% { opacity: 0; }
}

#slowmo-tint {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0;
  z-index: 6;
  background:
    radial-gradient(ellipse at center, transparent 30%, rgba(19, 58, 78, 0.22) 72%, rgba(3, 10, 15, 0.54) 100%);
  transition: opacity 0.18s ease;
}
#slowmo-tint.on { opacity: 1; }

#speedlines {
  position: absolute;
  inset: -25%;
  pointer-events: none;
  opacity: 0;
  z-index: 6;
  background: repeating-conic-gradient(from 0deg at 50% 48%, rgba(235, 251, 255, 0.9) 0deg 0.25deg, transparent 0.4deg 5.6deg);
  mask-image: radial-gradient(circle at 50% 48%, transparent 0 27%, #000 62%, transparent 82%);
  -webkit-mask-image: radial-gradient(circle at 50% 48%, transparent 0 27%, #000 62%, transparent 82%);
  transition: opacity 0.14s ease;
  animation: speedspin 8s linear infinite;
}
#speedlines.on { opacity: 0.32; }
@keyframes speedspin { to { transform: rotate(360deg); } }

/* ---------------- HUD ---------------- */

#hud {
  position: absolute;
  inset: 0;
  z-index: 10;
  pointer-events: none;
  padding: calc(14px + var(--safe-t)) calc(18px + var(--safe-r)) calc(16px + var(--safe-b)) calc(18px + var(--safe-l));
  opacity: 0;
  transition: opacity 0.35s ease;
}
#hud.visible { opacity: 1; }

.hud-tl {
  position: absolute;
  top: calc(16px + var(--safe-t));
  left: calc(20px + var(--safe-l));
  display: flex;
  align-items: flex-start;
  gap: 10px;
}

.hero-badge {
  width: clamp(34px, 4vw, 46px);
  height: clamp(34px, 4vw, 46px);
  display: grid;
  place-items: center;
  filter: drop-shadow(0 0 8px rgba(102, 229, 255, 0.45));
  opacity: 0.95;
}
.hero-badge svg { width: 100%; height: 100%; fill: #c7f4ff; }
.hero-badge .cut { fill: none; stroke: #0a1620; stroke-width: 3.4; stroke-linecap: round; }

.vitals { width: clamp(168px, 22vw, 260px); }
.nameplate {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  font-family: var(--font-display);
  font-size: clamp(15px, 1.5vw, 19px);
  letter-spacing: 0.14em;
  color: #d9f4ff;
  text-shadow: 0 1px 6px rgba(0, 0, 0, 0.85);
  margin-bottom: 3px;
}
.nameplate span:last-child { color: #7fa6b9; font-size: 0.8em; letter-spacing: 0.05em; }

.health-track {
  position: relative;
  height: clamp(11px, 1.35vw, 16px);
  background: rgba(8, 16, 25, 0.82);
  border: 1px solid rgba(158, 218, 239, 0.34);
  clip-path: polygon(0 0, 100% 0, calc(100% - 8px) 100%, 0 100%);
  overflow: hidden;
  box-shadow: 0 0 12px rgba(50, 170, 200, 0.12), inset 0 0 8px rgba(0, 0, 0, 0.6);
}
#health-fill {
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, #3fc7e6 0%, #9cefff 55%, #eaffff 100%);
  box-shadow: 0 0 14px rgba(110, 230, 255, 0.65);
  transition: width 0.28s cubic-bezier(0.2, 0.9, 0.2, 1), background 0.3s ease;
  transform-origin: left;
}
#health-fill.low {
  background: linear-gradient(90deg, #a40e1e, #ff4a5e 60%, #ffb0b9);
  box-shadow: 0 0 16px rgba(255, 58, 82, 0.62);
}
.health-ticks {
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(90deg, transparent 0 calc(10% - 1px), rgba(4, 11, 17, 0.7) calc(10% - 1px) 10%);
  pointer-events: none;
}
.special-line {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-top: 4px;
  font-size: 9px;
  letter-spacing: 0.24em;
  color: rgba(169, 202, 218, 0.75);
}
.special-line .mini-meter {
  flex: 1;
  height: 3px;
  background: rgba(20, 32, 44, 0.8);
  overflow: hidden;
}
#special-fill {
  width: 0%;
  height: 100%;
  background: linear-gradient(90deg, #8b6a16, #ffd36a 80%, #fff3c4);
  box-shadow: 0 0 8px rgba(255, 211, 106, 0.65);
  transition: width 0.2s linear;
}

#combo {
  position: absolute;
  top: calc(18px + var(--safe-t));
  left: 50%;
  transform: translateX(-50%) skewX(-7deg);
  display: flex;
  align-items: flex-end;
  gap: 6px;
  pointer-events: none;
  filter: drop-shadow(0 5px 16px rgba(0, 0, 0, 0.7));
}
#combo-num {
  font-family: var(--font-display);
  font-size: clamp(46px, 6.4vw, 78px);
  line-height: 0.8;
  color: #fff;
  text-shadow: 0 0 18px rgba(110, 230, 255, 0.5), 3px 3px 0 rgba(0, 30, 40, 0.65);
  transition: color 0.18s ease, transform 0.12s ease;
  display: inline-block;
}
#combo.pop #combo-num { animation: comboPop 0.22s cubic-bezier(0.15, 0.9, 0.25, 1.4); }
@keyframes comboPop {
  0% { transform: scale(1.34) rotate(-2deg); }
  100% { transform: scale(1) rotate(0); }
}
.combo-meta {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  padding-bottom: clamp(5px, 1vw, 11px);
  line-height: 1;
}
.combo-x { font-family: var(--font-display); font-size: clamp(15px, 1.7vw, 22px); color: var(--cyan); }
.combo-word {
  font-family: var(--font-ui);
  font-weight: 700;
  font-size: clamp(9px, 1vw, 12px);
  letter-spacing: 0.22em;
  color: rgba(213, 242, 255, 0.86);
}
#combo.hot #combo-num { color: var(--gold); text-shadow: 0 0 22px rgba(255, 196, 58, 0.7), 3px 3px 0 rgba(70, 25, 0, 0.55); }
#combo.blazing #combo-num { color: #ffb347; text-shadow: 0 0 26px rgba(255, 96, 32, 0.9), 3px 3px 0 rgba(85, 12, 0, 0.55); }
#combo.blazing .combo-x, #combo.blazing .combo-word { color: #ffcf8b; }

.hud-tr {
  position: absolute;
  top: calc(16px + var(--safe-t));
  right: calc(20px + var(--safe-r));
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 6px;
}
.wave-plate {
  display: flex;
  align-items: baseline;
  gap: 4px;
  font-family: var(--font-display);
  color: #d9f4ff;
  letter-spacing: 0.06em;
  font-size: clamp(20px, 2.2vw, 28px);
  line-height: 1;
  text-shadow: 0 2px 10px rgba(0, 0, 0, 0.8);
}
.wave-plate .eyebrow { font-family: var(--font-ui); font-size: 10px; font-weight: 700; letter-spacing: 0.28em; color: #76a4b9; margin-right: 2px; }
.wave-plate .slash { color: #56798a; }
#enemy-dots { display: flex; gap: 5px; height: 8px; align-items: center; }
#enemy-dots i {
  display: block;
  width: 7px;
  height: 7px;
  transform: rotate(45deg);
  background: #ff5568;
  box-shadow: 0 0 7px rgba(255, 62, 82, 0.65);
  transition: opacity 0.25s ease, transform 0.25s ease;
}
#enemy-dots i.down { background: #2a3a46; box-shadow: none; transform: rotate(45deg) scale(0.7); opacity: 0.5; }
.score-line { font-size: 10px; font-weight: 700; letter-spacing: 0.24em; color: rgba(165, 198, 214, 0.8); }
.score-line span { color: #e5f8ff; font-family: var(--font-display); font-size: 15px; letter-spacing: 0.05em; }

.hud-icons { display: flex; gap: 7px; margin-top: 2px; }
.icon-btn {
  pointer-events: auto;
  width: 34px;
  height: 34px;
  padding: 7px;
  border-radius: 4px;
  border: 1px solid rgba(141, 198, 218, 0.28);
  background: rgba(6, 12, 19, 0.58);
  color: #b9dce9;
  backdrop-filter: blur(4px);
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease, transform 0.1s ease;
}
.icon-btn:hover { border-color: rgba(141, 220, 246, 0.68); background: rgba(14, 31, 44, 0.72); }
.icon-btn:active { transform: scale(0.93); }
.icon-btn svg { width: 100%; height: 100%; fill: currentColor; }
.icon-btn .ico-off { display: none; }
.icon-btn.muted .ico-on { display: none; }
.icon-btn.muted .ico-off { display: block; }

#counter-cue {
  position: absolute;
  top: calc(25% + var(--safe-t));
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 12px 6px 7px;
  border: 1px solid rgba(194, 241, 255, 0.55);
  background: linear-gradient(90deg, rgba(24, 83, 104, 0.68), rgba(8, 22, 31, 0.3));
  clip-path: polygon(8px 0, 100% 0, calc(100% - 8px) 100%, 0 100%);
  animation: cuePulse 0.55s ease-in-out infinite alternate;
  backdrop-filter: blur(4px);
  filter: drop-shadow(0 0 14px rgba(102, 229, 255, 0.35));
}
.cue-key {
  display: grid;
  place-items: center;
  width: 24px;
  height: 24px;
  font-family: var(--font-ui);
  font-weight: 700;
  font-size: 13px;
  color: #04222c;
  background: #c9f3ff;
  clip-path: polygon(3px 0, 100% 0, 100% calc(100% - 3px), calc(100% - 3px) 100%, 0 100%, 0 3px);
}
.cue-text {
  font-family: var(--font-display);
  font-size: 18px;
  letter-spacing: 0.14em;
  color: #dbf8ff;
  text-shadow: 0 0 10px rgba(102, 229, 255, 0.7);
}
@keyframes cuePulse {
  from { transform: translateX(-50%) scale(1); filter: drop-shadow(0 0 8px rgba(102, 229, 255, 0.24)); }
  to { transform: translateX(-50%) scale(1.035); filter: drop-shadow(0 0 20px rgba(102, 229, 255, 0.55)); }
}
body.touch .cue-key { display: none; }

#toast {
  position: absolute;
  top: 37%;
  left: 50%;
  transform: translate(-50%, -50%) rotate(-1.5deg) scale(0.9);
  font-family: var(--font-impact);
  font-size: clamp(28px, 4.4vw, 54px);
  letter-spacing: 0.04em;
  color: #f2fdff;
  text-align: center;
  text-shadow:
    0 0 18px rgba(94, 229, 255, 0.8),
    0 4px 0 rgba(7, 39, 51, 0.9),
    3px 3px 0 rgba(0, 0, 0, 0.5);
  opacity: 0;
  pointer-events: none;
  white-space: nowrap;
  z-index: 3;
  transition: opacity 0.12s ease, transform 0.18s ease;
}
#toast.show { opacity: 1; transform: translate(-50%, -50%) rotate(-1.5deg) scale(1); }
#toast.gold { color: #ffdf8b; text-shadow: 0 0 22px rgba(255, 193, 54, 0.9), 0 4px 0 rgba(79, 40, 0, 0.9), 3px 3px 0 rgba(0, 0, 0, 0.5); }
#toast.red { color: #ff9aa5; text-shadow: 0 0 20px rgba(255, 42, 68, 0.8), 0 4px 0 rgba(65, 0, 8, 0.9); }

#banner {
  position: absolute;
  top: 42%;
  left: 50%;
  transform: translate(-50%, -50%);
  text-align: center;
  width: min(90vw, 640px);
  pointer-events: none;
  z-index: 4;
}
#banner.enter { animation: bannerIn 0.55s cubic-bezier(0.16, 0.9, 0.25, 1) both; }
#banner.exit { animation: bannerOut 0.4s ease both; }
@keyframes bannerIn {
  0% { opacity: 0; transform: translate(-50%, -50%) scale(1.35); filter: blur(4px); }
  100% { opacity: 1; transform: translate(-50%, -50%) scale(1); filter: blur(0); }
}
@keyframes bannerOut {
  0% { opacity: 1; transform: translate(-50%, -50%) scale(1); }
  100% { opacity: 0; transform: translate(-50%, -50%) scale(0.94); }
}
.banner-kicker {
  font-family: var(--font-ui);
  font-weight: 700;
  font-size: clamp(10px, 1.2vw, 14px);
  letter-spacing: 0.52em;
  color: var(--cyan);
  text-shadow: 0 0 14px rgba(102, 229, 255, 0.6);
  margin-bottom: 2px;
}
.banner-title {
  font-family: var(--font-display);
  font-size: clamp(48px, 8vw, 104px);
  line-height: 0.9;
  letter-spacing: 0.04em;
  color: #f3fdff;
  text-shadow: 0 0 30px rgba(117, 227, 255, 0.32), 0 7px 0 rgba(4, 17, 24, 0.65);
}
.banner-sub {
  font-family: var(--font-ui);
  font-weight: 500;
  font-size: clamp(10px, 1.1vw, 13px);
  letter-spacing: 0.36em;
  color: rgba(174, 213, 228, 0.82);
  margin-top: 5px;
}

#tutorial {
  position: absolute;
  bottom: calc(20px + var(--safe-b));
  left: 50%;
  transform: translateX(-50%);
  padding: 7px 16px;
  border-top: 1px solid rgba(128, 200, 222, 0.26);
  border-bottom: 1px solid rgba(128, 200, 222, 0.26);
  background: linear-gradient(90deg, transparent, rgba(7, 18, 27, 0.72) 20%, rgba(7, 18, 27, 0.72) 80%, transparent);
  font-size: clamp(10px, 1.1vw, 13px);
  letter-spacing: 0.16em;
  color: rgba(185, 224, 238, 0.9);
  white-space: nowrap;
  text-shadow: 0 1px 4px #000;
  pointer-events: none;
  transition: opacity 0.4s ease;
  z-index: 2;
}
#tutorial b { color: #d6f7ff; font-weight: 700; }

/* ---------------- joystick ---------------- */

#joy-zone {
  position: absolute;
  left: 0;
  bottom: 0;
  width: 46%;
  height: 62%;
  pointer-events: auto;
  touch-action: none;
  z-index: 2;
}
#joy-base {
  --joy-x: 20px;
  --joy-y: 0px;
  position: absolute;
  left: calc(22px + var(--safe-l));
  bottom: calc(24px + var(--safe-b));
  width: clamp(96px, 16vw, 136px);
  height: clamp(96px, 16vw, 136px);
  border-radius: 50%;
  border: 1px solid rgba(143, 210, 230, 0.24);
  background:
    radial-gradient(circle at 50% 50%, rgba(17, 39, 52, 0.18) 0 46%, rgba(132, 202, 224, 0.04) 47% 68%, transparent 69%),
    conic-gradient(from 45deg, transparent 0 23%, rgba(120, 198, 222, 0.12) 24% 26%, transparent 27% 73%, rgba(120, 198, 222, 0.12) 74% 76%, transparent 77%);
  box-shadow: inset 0 0 24px rgba(0, 0, 0, 0.34), 0 0 20px rgba(22, 86, 108, 0.12);
  opacity: 0.8;
  transition: opacity 0.2s ease, border-color 0.2s ease, transform 0.12s ease;
  transform: translate(var(--joy-x), var(--joy-y));
  will-change: transform;
}
#joy-base.active {
  opacity: 1;
  border-color: rgba(140, 228, 252, 0.5);
  box-shadow: inset 0 0 30px rgba(0, 0, 0, 0.4), 0 0 26px rgba(46, 155, 190, 0.18);
}
#joy-base .joy-cross {
  position: absolute;
  inset: 22%;
  border-radius: 50%;
  border: 1px dashed rgba(141, 209, 230, 0.14);
}
#joy-knob {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 42%;
  height: 42%;
  margin: -21% 0 0 -21%;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, rgba(213, 247, 255, 0.75), rgba(76, 160, 187, 0.55) 45%, rgba(10, 34, 45, 0.92) 100%);
  border: 1px solid rgba(191, 241, 255, 0.55);
  box-shadow: 0 0 14px rgba(94, 220, 255, 0.25), inset 0 0 10px rgba(0, 0, 0, 0.4);
  will-change: transform;
}
#joy-base.active #joy-knob { box-shadow: 0 0 22px rgba(114, 231, 255, 0.5), inset 0 0 10px rgba(0, 0, 0, 0.4); }

/* ---------------- action buttons ---------------- */

#actions {
  position: absolute;
  right: calc(20px + var(--safe-r));
  bottom: calc(20px + var(--safe-b));
  width: clamp(190px, 26vw, 280px);
  height: clamp(170px, 22vw, 238px);
  pointer-events: none;
  z-index: 3;
}
.action {
  position: absolute;
  pointer-events: auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 3px;
  padding: 0;
  border-radius: 50%;
  border: 1px solid rgba(156, 207, 223, 0.32);
  background:
    radial-gradient(circle at 34% 26%, rgba(45, 74, 89, 0.62), rgba(8, 19, 27, 0.86) 62%),
    rgba(5, 13, 20, 0.72);
  color: #d8f4ff;
  box-shadow: 0 5px 18px rgba(0, 0, 0, 0.5), inset 0 0 16px rgba(114, 208, 235, 0.08);
  backdrop-filter: blur(4px);
  touch-action: none;
  transition: transform 0.08s ease, box-shadow 0.14s ease, border-color 0.14s ease, opacity 0.2s ease;
  -webkit-user-select: none;
  user-select: none;
}
.action svg { width: 42%; height: 42%; fill: currentColor; flex: 0 0 auto; }
.action .act-label {
  font-size: clamp(6px, 0.7vw, 9px);
  font-weight: 700;
  letter-spacing: 0.16em;
  color: rgba(191, 227, 239, 0.82);
  line-height: 1;
}
.action:active, .action.pressed { transform: scale(0.92); }
.action.disabled { opacity: 0.34; }
.action.ready { animation: actionReady 0.8s ease-in-out infinite alternate; }

.act-attack {
  right: 0;
  bottom: 0;
  width: clamp(72px, 11.5vw, 106px);
  height: clamp(72px, 11.5vw, 106px);
  border-color: rgba(157, 233, 255, 0.5);
  color: #d9f7ff;
  background:
    radial-gradient(circle at 35% 28%, rgba(63, 130, 154, 0.7), rgba(8, 24, 34, 0.9) 60%),
    rgba(5, 13, 20, 0.78);
  box-shadow: 0 0 26px rgba(54, 185, 220, 0.18), 0 6px 20px rgba(0, 0, 0, 0.55), inset 0 0 18px rgba(114, 208, 235, 0.13);
}
.act-counter {
  right: clamp(78px, 12vw, 112px);
  bottom: clamp(8px, 1.2vw, 16px);
  width: clamp(52px, 7.6vw, 72px);
  height: clamp(52px, 7.6vw, 72px);
}
.act-dodge {
  right: clamp(6px, 0.8vw, 10px);
  bottom: clamp(84px, 12.4vw, 118px);
  width: clamp(50px, 7.2vw, 68px);
  height: clamp(50px, 7.2vw, 68px);
}
.act-special {
  right: clamp(76px, 11.6vw, 108px);
  bottom: clamp(82px, 12vw, 114px);
  width: clamp(50px, 7.2vw, 68px);
  height: clamp(50px, 7.2vw, 68px);
  color: #ffe6a0;
  border-color: rgba(224, 187, 92, 0.4);
}
.act-special.disabled { opacity: 0.38; filter: grayscale(0.6); }
.act-special.ready {
  animation: specialReady 0.9s ease-in-out infinite alternate;
  color: #fff1bd;
}
@keyframes specialReady {
  from { box-shadow: 0 0 10px rgba(255, 211, 106, 0.2), inset 0 0 14px rgba(255, 211, 106, 0.08); border-color: rgba(229, 190, 93, 0.45); }
  to { box-shadow: 0 0 30px rgba(255, 200, 77, 0.62), inset 0 0 20px rgba(255, 211, 106, 0.16); border-color: #ffd974; }
}
@keyframes actionReady {
  from { box-shadow: 0 0 10px rgba(120, 232, 255, 0.2), inset 0 0 12px rgba(120, 232, 255, 0.1); border-color: rgba(170, 238, 255, 0.5); }
  to { box-shadow: 0 0 30px rgba(120, 232, 255, 0.72), inset 0 0 20px rgba(120, 232, 255, 0.22); border-color: #d9fbff; }
}
.act-counter.ready { color: #f2feff; }
.act-counter.ready .pulse-ring {
  position: absolute;
  inset: -5px;
  border-radius: 50%;
  border: 1px solid rgba(142, 237, 255, 0.7);
  animation: ringPulse 0.7s ease-out infinite;
}
@keyframes ringPulse {
  0% { transform: scale(0.9); opacity: 0.9; }
  100% { transform: scale(1.35); opacity: 0; }
}
.meter-ring {
  position: absolute;
  inset: -3px;
  border-radius: 50%;
  padding: 2px;
  background: conic-gradient(from -90deg, #ffd36a calc(var(--meter, 0) * 1%), rgba(255, 211, 106, 0.08) 0);
  -webkit-mask: radial-gradient(farthest-side, transparent calc(100% - 3px), #000 calc(100% - 2px));
  mask: radial-gradient(farthest-side, transparent calc(100% - 3px), #000 calc(100% - 2px));
  pointer-events: none;
}
body.touch .act-label { letter-spacing: 0.08em; }

#rotate-hint {
  display: none;
  position: absolute;
  left: 50%;
  top: calc(64px + var(--safe-t));
  transform: translateX(-50%);
  font-size: 9px;
  letter-spacing: 0.18em;
  color: rgba(170, 211, 225, 0.68);
  padding: 5px 10px;
  border: 1px solid rgba(120, 178, 197, 0.22);
  background: rgba(4, 12, 18, 0.5);
  white-space: nowrap;
  animation: rotateHint 9s ease forwards;
}
#rotate-hint span { font-size: 13px; margin-right: 4px; color: var(--cyan); }
@keyframes rotateHint {
  0%, 80% { opacity: 0.75; }
  100% { opacity: 0; visibility: hidden; }
}

/* ---------------- screens / menu ---------------- */

.screen {
  position: absolute;
  inset: 0;
  z-index: 20;
  display: flex;
  flex-direction: column;
  justify-content: center;
  pointer-events: auto;
}

#menu {
  padding: calc(28px + var(--safe-t)) calc(30px + var(--safe-r)) calc(22px + var(--safe-b)) calc(46px + var(--safe-l));
  justify-content: flex-start;
  background:
    linear-gradient(90deg, rgba(2, 6, 11, 0.93) 0%, rgba(2, 7, 12, 0.83) 27%, rgba(2, 8, 13, 0.38) 57%, rgba(2, 8, 13, 0.04) 76%, rgba(2, 6, 10, 0.28) 100%),
    linear-gradient(180deg, rgba(2, 6, 10, 0.28) 0%, transparent 26%, transparent 58%, rgba(2, 6, 10, 0.8) 100%);
}
.menu-wash {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(ellipse at 78% 42%, rgba(29, 110, 138, 0.2), transparent 45%),
    repeating-linear-gradient(0deg, transparent 0 2px, rgba(0, 0, 0, 0.05) 2px 3px);
  mix-blend-mode: screen;
  opacity: 0.7;
}
.menu-bat {
  position: absolute;
  right: 6%;
  top: 50%;
  width: min(42vw, 470px);
  transform: translateY(-50%);
  opacity: 0.03;
  pointer-events: none;
  filter: blur(0.3px);
}
.menu-bat svg { width: 100%; height: auto; fill: #c9f4ff; }

.menu-content {
  position: relative;
  z-index: 2;
  margin-top: auto;
  margin-bottom: auto;
  max-width: 560px;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: clamp(16px, 3.2vh, 34px);
  animation: menuIn 0.9s cubic-bezier(0.16, 0.9, 0.25, 1) both;
}
@keyframes menuIn {
  from { opacity: 0; transform: translateY(18px); }
  to { opacity: 1; transform: translateY(0); }
}
.brand-kicker {
  display: flex;
  align-items: center;
  gap: 9px;
  font-size: clamp(8px, 0.8vw, 10px);
  font-weight: 700;
  letter-spacing: 0.36em;
  color: #8dc8da;
  margin-bottom: 6px;
  text-shadow: 0 1px 6px #000;
}
.brand-kicker .line { width: 26px; height: 1px; background: linear-gradient(90deg, transparent, #67cbe6); }
.brand-kicker .line:last-child { background: linear-gradient(90deg, #67cbe6, transparent); }

.logo {
  margin: 0;
  font-family: var(--font-display);
  font-size: clamp(78px, 12.4vw, 178px);
  line-height: 0.74;
  letter-spacing: 0.015em;
  font-weight: 400;
  display: flex;
  flex-direction: column;
  filter: drop-shadow(0 8px 26px rgba(0, 0, 0, 0.75));
}
.logo-night {
  color: #eefcff;
  text-shadow:
    0 0 30px rgba(123, 224, 255, 0.22),
    0 3px 0 #4d6e7e,
    0 6px 0 #1b313d,
    0 9px 22px rgba(0, 0, 0, 0.8);
}
.logo-fall {
  color: transparent;
  background: linear-gradient(180deg, #ffdf8e 0%, #ffb838 38%, #b06c09 78%, #6a3b00 100%);
  -webkit-background-clip: text;
  background-clip: text;
  text-shadow: none;
  filter: drop-shadow(0 3px 0 rgba(90, 47, 0, 0.9)) drop-shadow(0 0 28px rgba(255, 173, 38, 0.18));
  margin-left: clamp(30px, 6.6vw, 96px);
}
.brand-sub {
  margin: 7px 0 0;
  font-family: var(--font-ui);
  font-weight: 700;
  font-size: clamp(10px, 1.15vw, 14px);
  letter-spacing: 0.34em;
  color: rgba(192, 223, 234, 0.76);
  text-shadow: 0 1px 8px #000;
}
.menu-actions { display: flex; flex-direction: column; align-items: flex-start; gap: 10px; }

.primary-btn {
  position: relative;
  pointer-events: auto;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
  min-width: clamp(230px, 26vw, 330px);
  padding: clamp(12px, 1.5vh, 18px) clamp(22px, 2.6vw, 34px) clamp(10px, 1.3vh, 15px);
  border: 1px solid rgba(185, 240, 255, 0.6);
  background:
    linear-gradient(100deg, rgba(84, 198, 226, 0.22), rgba(9, 30, 42, 0.68) 38%, rgba(6, 18, 27, 0.82)),
    #08161f;
  color: #f0fdff;
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 10px), calc(100% - 10px) 100%, 0 100%);
  cursor: pointer;
  overflow: hidden;
  box-shadow: 0 0 26px rgba(59, 179, 210, 0.12), inset 0 0 24px rgba(95, 213, 241, 0.06);
  transition: border-color 0.2s ease, transform 0.1s ease, box-shadow 0.2s ease;
}
.primary-btn .btn-shine {
  position: absolute;
  top: 0;
  left: -40%;
  width: 30%;
  height: 100%;
  background: linear-gradient(100deg, transparent, rgba(210, 250, 255, 0.18), transparent);
  transform: skewX(-18deg);
  animation: shine 4.2s ease-in-out infinite;
}
@keyframes shine {
  0%, 60% { left: -40%; }
  85%, 100% { left: 130%; }
}
.primary-btn:hover { border-color: #d8fbff; box-shadow: 0 0 36px rgba(76, 207, 240, 0.3), inset 0 0 26px rgba(95, 213, 241, 0.12); }
.primary-btn:active { transform: scale(0.985); }
.btn-main {
  font-family: var(--font-display);
  font-size: clamp(24px, 3vw, 38px);
  line-height: 1;
  letter-spacing: 0.07em;
  text-shadow: 0 0 16px rgba(99, 223, 255, 0.35);
}
.btn-sub {
  font-size: clamp(7px, 0.72vw, 9px);
  font-weight: 700;
