.result b { font-family: var(--font-display); font-size: clamp(26px, 3.6vw, 40px); letter-spacing: 0.04em; color: #e9fbff; font-weight: 400; }
.results-best { min-height: 16px; margin-bottom: 18px; font-size: 9px; font-weight: 700; letter-spacing: 0.28em; color: var(--gold); text-shadow: 0 0 12px rgba(255, 211, 106, 0.55); }
