/* ---------------- responsive ---------------- */

@media (max-width: 900px) {
  #menu { padding-left: calc(30px + var(--safe-l)); background: linear-gradient(90deg, rgba(2, 6, 11, 0.92) 0%, rgba(2, 7, 12, 0.72) 34%, rgba(2, 8, 13, 0.16) 72%, rgba(2, 6, 10, 0.3) 100%), linear-gradient(180deg, rgba(2, 6, 10, 0.3) 0%, transparent 30%, transparent 58%, rgba(2, 6, 10, 0.85) 100%); }
