import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync('/home/runner/.local/share/omgithub-playwright/linux.json', 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync('/home/runner/.local/share/omgithub-playwright/display', 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
const errors = [];
page.on('pageerror', e => errors.push(e.message));
page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
const response = await page.goto('http://localhost:3000', { waitUntil: 'load' });
await page.waitForFunction(() => document.fonts.status === 'loaded');
await page.waitForTimeout(1000);
console.log('load', response.status(), 'boot', await page.locator('#boot').getAttribute('class'), 'menu', await page.locator('#menu').getAttribute('class'));
await page.locator('#start-btn').click();
await page.waitForTimeout(2400);
console.log('game', await page.locator('#hud').getAttribute('class'), 'wave', await page.locator('#wave-num').textContent(), 'enemies', await page.locator('#enemy-dots').locator('i').count());
await page.keyboard.press('j');
await page.waitForTimeout(500);
console.log('combat score', await page.locator('#score').textContent(), 'combo', await page.locator('#combo-num').textContent());
await page.locator('#pause-btn').click();
console.log('pause', await page.locator('#pause-menu').getAttribute('class'));
await page.locator('#resume-btn').click();
await page.waitForTimeout(800);
mkdirSync('/tmp/opencode', { recursive: true });
await page.screenshot({ path: '/tmp/opencode/nightfall-latest.jpg', type: 'jpeg', quality: 78 });
console.log('screenshot /tmp/opencode/nightfall-latest.jpg 1280x720 errors', JSON.stringify(errors));
await browser.close();

