import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync('/home/runner/.local/share/omgithub-playwright/linux.json', 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync('/home/runner/.local/share/omgithub-playwright/display', 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 915, height: 412 }, isMobile: true, hasTouch: true, deviceScaleFactor: 1 });
const errors = [];
page.on('pageerror', e => errors.push(e.message));
page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
await page.goto('http://localhost:3000', { waitUntil: 'load' });
await page.locator('#start-btn').tap();
await page.waitForTimeout(3500);
const base = await page.locator('#joy-base').boundingBox();
const cdp = await page.context().newCDPSession(page);
await cdp.send('Input.dispatchTouchEvent', { type:'touchStart', touchPoints:[{x:base.x+base.width/2,y:base.y+base.height/2}] });
await cdp.send('Input.dispatchTouchEvent', { type:'touchMove', touchPoints:[{x:base.x+base.width/2+40,y:base.y+base.height/2}] });
console.log('joystick moved', await page.locator('#joy-knob').getAttribute('style'));
await page.waitForTimeout(300);
await cdp.send('Input.dispatchTouchEvent', { type:'touchEnd', touchPoints:[] });
console.log('joystick released', await page.locator('#joy-knob').getAttribute('style'));
await page.locator('#btn-attack').tap();
await page.waitForTimeout(500);
console.log('touch strike score', await page.locator('#score').textContent());
await page.screenshot({path:'/tmp/opencode/nightfall-latest.jpg',type:'jpeg',quality:78});
await page.locator('#pause-btn').tap();
console.log('pause visible', await page.locator('#pause-menu').isVisible());
await page.locator('#restart-btn').tap();
console.log('restart score', await page.locator('#score').textContent(), 'wave', await page.locator('#wave-num').textContent());
let lastWave='';
for (let i=0;i<100;i++) {
  if (await page.locator('#results').isVisible()) break;
  const wave = await page.locator('#wave-num').textContent();
  if(wave !== lastWave) { console.log('wave',wave); lastWave=wave; }
  await page.locator('#btn-attack').tap();
  await page.waitForTimeout(500);
}
console.log('results', await page.locator('#results').isVisible(), 'title', await page.locator('#results-title').textContent(), 'score',await page.locator('#result-score').textContent());
if(await page.locator('#results').isVisible()) {
  await page.locator('#again-btn').tap();
  console.log('fight again wave',await page.locator('#wave-num').textContent(),'score',await page.locator('#score').textContent());
  await page.locator('#pause-btn').tap();
  await page.locator('#quit-btn').tap();
  console.log('menu visible',await page.locator('#menu').isVisible());
}
console.log('errors',JSON.stringify(errors));
await browser.close();
